import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachFreeControl } from "@babylonjs/lite";

const BIG_WORLD_MOVEMENT_MULTIPLIER = 20;

export function attachBigWorldFly(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  const previousSpeed = camera.speed;
  camera.speed = previousSpeed * BIG_WORLD_MOVEMENT_MULTIPLIER;

  let detachControl: (() => void) | undefined;
  try {
    detachControl = attachFreeControl(camera, canvas, scene);
  } catch (error) {
    camera.speed = previousSpeed;
    throw error;
  }

  if (detachControl === undefined) {
    camera.speed = previousSpeed;
    throw new Error("attachFreeControl did not return a disposer.");
  }

  const dispose = detachControl;
  let disposed = false;

  return () => {
    if (disposed) {
      return;
    }
    disposed = true;

    try {
      dispose();
    } finally {
      camera.speed = previousSpeed;
    }
  };
}
```

I attached the library’s default free controls and scaled `camera.speed` by 20 while attached, restoring it on dispose so the library’s own listeners and frame work are removed. I was not certain of the exact rise/sink key names, so I scaled the camera speed rather than remapping keys; I also assumed the default controls read `camera.speed` each frame.
